steps.script:
window.__arPage = {
  page: () => document.querySelector('#AccessRolesConfigPage:not(.hide)'),
  panels: () => [...document.querySelectorAll('.jfar-backdrop .jfar-panel')],
  top: () => __arPage.panels().pop() || null,
  title: () => { const t = __arPage.top(); return t ? t.querySelector('.jfar-panel-header h3').textContent : null; },
  buttons: (root) => [...(root || document).querySelectorAll('button')],
  button: (root, text) => __arPage.buttons(root).find(b => b.textContent === text) || null,
  press: (root, text) => { const b = __arPage.button(root, text); if (!b) throw new Error('no button ' + text); if (b.disabled) throw new Error(text + ' is disabled'); b.click(); return true; },
  user: (name) => [...__arPage.page().querySelectorAll('.jfar-page-user')].find(r => r.querySelector('.jfar-page-user-name').textContent === name) || null,
  role: (name) => [...__arPage.page().querySelectorAll('.jfar-page-role')].find(r => r.querySelector('.jfar-page-role-name').textContent === name) || null,
  check: (root, text) => { const l = [...root.querySelectorAll('label')].find(l => l.textContent.startsWith(text)); return l ? l.querySelector('input') : null; },
  shown: (el) => !!el && el.getClientRects().length > 0 && !el.closest('[hidden]'),
  seen: [],
  toasts: () => __arPage.seen.concat([...document.querySelectorAll('.jfar-toast')].map(t => t.textContent)),
  // Another administrator, through the API (the page's own session; the review's races).
  api: (type, path, body) => ApiClient.ajax({ type, url: ApiClient.getUrl(path), data: body ? JSON.stringify(body) : undefined, contentType: 'application/json', dataType: 'json' }),
  rows: () => ApiClient.getJSON(ApiClient.getUrl('AccessRoles/Admin/Users')),
  row: async (name) => (await __arPage.rows()).find(r => r.Name === name) || null,
  // The dialog's 409 Changed sentence when it is shown, else null.
  stale: () => { const t = __arPage.top(); const s = t && t.querySelector('.jfar-page-stale'); return s && __arPage.shown(s) ? s.querySelector('.jfar-page-stale-text').textContent : null; },
  previewLines: () => [...__arPage.top().querySelectorAll('.jfar-page-preview-line')].map(l => l.textContent)
};
// Every toast's text as it comes (a toast goes after 4 s, maybe before a wait sees it).
new MutationObserver(() => { document.querySelectorAll('.jfar-toast').forEach(t => { if (!__arPage.seen.includes(t.textContent)) __arPage.seen.push(t.textContent); }); }).observe(document.body, { childList: true, subtree: true });
return true;
